edits.new:
// Tautan dicetak pada baris tersendiri agar URL panjang tidak terpotong dan tetap dapat diklik.
j.references.forEach((r, i) => {
	const url = j.refLinks?.[i];
	para(r, { hang: 28, size: 9.5, after: url ? 1 : 5 });
	if (url) {
		para(url, { size: 8.5, indent: 28, after: 7, color: rgb(0.02, 0.39, 0.76), anchor: { text: url, url } });
	}
});
